// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;

    function setUp() public { c = new PoCGame(address(this), 0); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        bool before = c.currentBetLimit() >= 0 ? (c.hasPlayerWagered(address(0)) == false) : true;

        bool ok;
        try c.OpenToThePublic() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == true);
    }
}
